-- Imágenes ilustrativas de los 25 modelos del catálogo de Lima.
-- Ejecutar después de cargar el SQL original. Se conservan las fotos ya registradas.
SET NAMES utf8mb4;
USE tienda_online;
CREATE TABLE IF NOT EXISTS imagen_producto_color (
    id_producto INT NOT NULL,
    id_color INT NOT NULL,
    contenido MEDIUMBLOB NOT NULL,
    PRIMARY KEY (id_producto, id_color),
    FOREIGN KEY (id_producto) REFERENCES producto(id_producto) ON DELETE CASCADE ON UPDATE CASCADE,
    FOREIGN KEY (id_color) REFERENCES color(id_color) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB;
START TRANSACTION;

INSERT INTO imagen_producto_color (id_producto, id_color, contenido)
SELECT p.id_producto, c.id_color, X''
FROM producto p JOIN color c ON c.nombre = 'Blanco'
LEFT JOIN imagen_producto_color i ON i.id_producto = p.id_producto AND i.id_color = c.id_color
WHERE p.sku = 'DEMO-LIM-PO001' AND i.id_producto IS NULL;

