COMMIT;
SELECT COUNT(*) AS combinaciones_con_imagen FROM imagen_producto_color;
SELECT DISTINCT p.sku, c.nombre AS color_sin_imagen
FROM variante_producto v JOIN producto p USING (id_producto) JOIN color c USING (id_color)
LEFT JOIN imagen_producto_color i ON i.id_producto = v.id_producto AND i.id_color = v.id_color
WHERE i.id_producto IS NULL;
